// ❌ OLD: CommonJS allows fully dynamic, synchronous requires.
// require() takes a runtime-computed path and executes immediately.
// Flexible, but: it's synchronous (blocks the event loop while the
// module loads), it cannot be statically analyzed (no tree-shaking),
// and cycles are resolved with partial exports.
function loadPlugin(name) {
  return require(`./plugins/${name}`); // ❌ OLD: dynamic path + sync exec
}

// Conditional loading is trivial:
const logger = process.env.DEBUG ? require('./verbose') : require('./quiet');

// ✅ NEW: ESM imports are static and hoisted — the loader resolves the
// whole graph before executing anything, enabling tree-shaking and
// deterministic dependency order.
import { helper } from './helper.js'; // ✅ NEW: static import

// ✅ NEW: dynamic loading is async via import(), which returns a
// promise of the module namespace (and supports top-level await).
async function loadPlugin(name) {
  const mod = await import(`./plugins/${name}.js`); // ✅ NEW: async
  return mod.default;
}

